def set_defined_name(path: WorkbookPath, name: DefinedName, refers_to: Annotated[str, Field(description="Range with sheet, 'Data!$B$2:$B$100', or a constant, '0.075'.")], sheet: NameScope=None) -> Changed:
    """Create a defined name for a range or constant (usable in formulas, '=SUM(Sales)'),
        replacing one of the same scope. The reference follows the formula safety rules."""
    with workspace.edit(path) as workbook:
        replaced = names.set_defined_name(workbook, name, refers_to, get_sheet(workbook, sheet) if sheet else None)
    note = 'Replaced the earlier definition.' if replaced else None
    return Changed(sheet=sheet, name=name, note=note)

